const byModule=new Map<string,ReadonlySet<string>>(groups.map(group=>[group.module,new Set<string>(group.identities.map(row=>row.objectId))]));
export function delegated500ModuleCandidate(module:string,rows:readonly Pick<Delegated500DataIdentity,'objectId'>[]):boolean{const ids=byModule.get(module);return !ids||rows.some(row=>ids.has(row.objectId));}
export function delegated500DemandClosure(input:readonly Delegated500DataIdentity[]){
 const identities=new Map(input.map(row=>[row.city+'|'+row.objectId+'|'+row.partId,{city:row.city,objectId:row.objectId,partId:row.partId}])),objects=new Set(input.map(row=>row.objectId)),selected=new Set<string>(),families=new Set<number>();
 for(let changed=true;changed;){changed=false;for(const group of groups){if(selected.has(group.module)||!group.identities.some(row=>objects.has(row.objectId)))continue;selected.add(group.module);for(const family of group.families)families.add(family);for(const row of group.identities){const key=row.city+'|'+row.objectId+'|'+row.partId;if(!identities.has(key)){identities.set(key,{...row});objects.add(row.objectId);changed=true;}}}}
 return{identities:[...identities.values()],families:[...families],modules:selected};
}
